        if($publication&&Uuid::isValid($publication)){$where[]='e.publication_guid=?';$params[]=Uuid::toBinary($publication);}if($city&&Uuid::isValid($city)){$where[]='e.city_guid=?';$params[]=Uuid::toBinary($city);}if($language&&Uuid::isValid($language)){$where[]='e.language_guid=?';$params[]=Uuid::toBinary($language);}
        $rows=TenantData::editionsWithCovers(implode(' AND ',$where),$params,200);$filters=PublicReadCache::archiveFilters();$pubs=$filters['publications'];$cities=$filters['cities'];$langs=$filters['languages'];
        $base=['publication'=>$publication,'city'=>$city,'language'=>$language];$prevMonth=$monthDt->modify('-1 month')->format('Y-m');$nextMonth=$monthDt->modify('+1 month')->format('Y-m');
        $html='<section class="archive-head"><div class="archive-title-row"><div><span class="eyebrow">ARCHIVE</span><h1>Previous editions</h1><p>Browse the newspaper by date, publication, city or language.</p></div><a class="btn ghost" href="/">Today’s edition</a></div>';
        $html.='<div class="archive-date-panel"><div class="archive-month-row"><a class="date-nav-btn" href="'.$this->e($this->archiveUrl($base+['month'=>$prevMonth,'year'=>substr($prevMonth,0,4)] )).'" aria-label="Previous month">'.View::icon('chev-left').'</a><div><span class="eyebrow">ARCHIVE MONTH</span><strong>'.$this->e($monthDt->format('F Y')).'</strong></div><a class="date-nav-btn" href="'.$this->e($this->archiveUrl($base+['month'=>$nextMonth,'year'=>substr($nextMonth,0,4)] )).'" aria-label="Next month">'.View::icon('chev-right').'</a></div>';
        $html.='<div class="archive-date-rail" role="list" aria-label="Edition dates">';$days=(int)$monthDt->format('t');for($d=1;$d<=$days;$d++){$day=$monthDt->setDate((int)$monthDt->format('Y'),(int)$monthDt->format('m'),$d);$key=$day->format('Y-m-d');$count=(int)($calendar[$key]??0);$active=$dateValid&&$date===$key;$classes='archive-day'.($active?' active':'').(!$count?' unavailable':'');if($count){$href=$this->archiveUrl($base+['date'=>$key,'year'=>$day->format('Y'),'month'=>$day->format('Y-m')]);$html.='<a class="'.$classes.'" role="listitem" href="'.$this->e($href).'"'.($active?' aria-current="date"':'').'><span>'.$this->e($day->format('D')).'</span><strong>'.$this->e($day->format('d')).'</strong><small>'.$count.' '.($count===1?'edition':'editions').'</small></a>';}else{$html.='<span class="'.$classes.'" role="listitem" aria-disabled="true" aria-label="'.$this->e($day->format('D d M')).' · no edition"><span>'.$this->e($day->format('D')).'</span><strong>'.$this->e($day->format('d')).'</strong><small class="archive-day-empty" aria-hidden="true">—</small></span>';}}$html.='</div>';
