        $html.='<form class="archive-filter archive-toolbar" method="get"><input type="hidden" name="month" value="'.$this->e($month).'">'.($dateValid?'<input type="hidden" name="date" value="'.$this->e($date).'">':'').($range==='7'?'<input type="hidden" name="range" value="7">':'').'<label>Publication<select name="publication"><option value="">All publications</option>'.$this->optionRows($pubs,'publication_guid','name',$publication).'</select></label><label>City<select name="city"><option value="">All cities</option>'.$this->optionRows($cities,'city_guid','name',$city).'</select></label><label>Language<select name="language"><option value="">All languages</option>'.$this->optionRows($langs,'language_guid','name',$language).'</select></label><label>Year<input type="number" name="year" value="'.$year.'" min="2000" max="2100"></label><button class="btn" type="submit">Apply filters</button></form></section>';
        $title=$dateValid?date('l, d F Y',strtotime($date)):($range==='7'?'Last 7 days':'All editions in '.$year);$html.='<section class="archive-results"><div class="section-head archive-result-head"><div><span class="eyebrow">AVAILABLE EDITIONS</span><h2>'.$this->e($title).'</h2></div><span class="archive-count"><strong>'.count($rows).'</strong> '.(count($rows)===1?'edition':'editions').'</span></div><div class="archive-grid">';
        foreach($rows as$r){$img=$this->editionCoverUrl($r,'THUMB');$meta=array_values(array_filter([trim((string)($r['city_name']??'')),trim((string)($r['language_name']??'')),((int)$r['page_count']>0?(int)$r['page_count'].' pages':'')]));$html.='<a class="archive-edition" href="/edition/'.$this->e($r['slug']).'/page/1"><span class="archive-cover">'.($img?'<img src="'.$this->e($img).'" alt="Front page of '.$this->e($r['publication_name']).'" loading="lazy" decoding="async"'.(!empty($r['thumb_width'])&&!empty($r['thumb_height'])?' width="'.(int)$r['thumb_width'].'" height="'.(int)$r['thumb_height'].'"':'').'>':'<span class="paper-placeholder cover-missing"><span>Thumbnail unavailable</span></span>').'</span><span class="archive-edition-copy"><span class="eyebrow">'.$this->e(strtoupper((string)$r['publication_name'])).'</span><strong>'.$this->e($r['publication_name']).'</strong><time datetime="'.$this->e($r['edition_date']).'">'.$this->e(date('d M Y',strtotime($r['edition_date']))).'</time><small>'.$this->e(implode(' · ',$meta)).'</small><b>Open edition →</b></span></a>';}$html.='</div>';if(!$rows)$html.='<section class="empty-state archive-empty"><h2>No editions on this view</h2><p>Choose another available date or adjust the publication, city and language filters.</p><a class="btn" href="/archive">Reset archive</a></section>';$html.='</section>';View::layout('Archive',$html,['brand'=>$this->brandName(),'canonical_url'=>Http::origin().'/archive']);
