    private function archiveUrl(array $params): string
    {
        $allowed=['publication','city','language','year','date','range','month'];$clean=[];foreach($allowed as$key){if(!array_key_exists($key,$params))continue;$v=trim((string)$params[$key]);if($v==='')continue;$clean[$key]=$v;}return '/archive'.($clean?'?'.http_build_query($clean,'','&',PHP_QUERY_RFC3986):'');
    }

    private function search(): never
    {
        $q=trim((string)($_GET['q']??''));$results=$q?$this->searchRows($q,50):[];$html='<section class="page-head"><span class="eyebrow">OCR SEARCH</span><h1>Search the newspaper</h1><form class="search-form"><input name="q" value="'.$this->e($q).'" placeholder="Search words, names or phrases" autofocus><button class="btn primary">Search</button></form></section>';if($q){$html.='<div class="search-results"><p class="muted">'.count($results).' results</p>';foreach($results as$r){$snippet=$this->snippet($r['text_content'],$q);$html.='<a class="search-result" href="/edition/'.$this->e($r['edition_slug']).'/page/'.(int)$r['page_number'].'"><strong>'.$this->e($r['publication_name']).' · Page '.(int)$r['page_number'].'</strong><span>'.$this->e(date('d M Y',strtotime($r['edition_date']))).'</span><p>'.$this->e($snippet).'</p></a>';}$html.='</div>';}View::layout('Search',$html,['brand'=>$this->brandName(),'canonical_url'=>Http::origin().'/search','robots'=>'noindex,follow']);
    }

    private function searchRows(string $q,int $limit): array
    {
        if(mb_strlen($q)<2)return[];$rev=RuntimeCache::generation(RequestContext::tenantGuid(),'public-editions');return MultiLayerCache::remember('search:r'.$rev.':'.hash('sha256',mb_strtolower($q).'|'.$limit),60,300,function()use($q,$limit){$sql='SELECT o.text_content,p.page_number,e.slug edition_slug,e.edition_date,pub.name publication_name FROM ep_page_ocr o JOIN ep_pages p ON p.page_guid=o.page_guid JOIN ep_editions e ON e.edition_guid=p.edition_guid JOIN ep_publications pub ON pub.publication_guid=e.publication_guid WHERE o.tenant_guid=? AND e.status="PUBLISHED" AND MATCH(o.text_content) AGAINST(? IN NATURAL LANGUAGE MODE) ORDER BY MATCH(o.text_content) AGAINST(? IN NATURAL LANGUAGE MODE) DESC LIMIT '.(int)$limit;try{return Store::all($sql,[TenantData::tenantBin(),$q,$q]);}catch(\Throwable){return Store::all('SELECT o.text_content,p.page_number,e.slug edition_slug,e.edition_date,pub.name publication_name FROM ep_page_ocr o JOIN ep_pages p ON p.page_guid=o.page_guid JOIN ep_editions e ON e.edition_guid=p.edition_guid JOIN ep_publications pub ON pub.publication_guid=e.publication_guid WHERE o.tenant_guid=? AND e.status="PUBLISHED" AND o.text_content LIKE ? LIMIT '.(int)$limit,[TenantData::tenantBin(),'%'.$q.'%']);}});
    }

    private function snippet(string $text,string $q): string{$plain=preg_replace('/\s+/u',' ',trim($text));$pos=mb_stripos($plain,$q);if($pos===false)return mb_substr($plain,0,230).'…';return($pos>70?'…':'').mb_substr($plain,max(0,$pos-70),230).'…';}

    private function article(string $slug): never
    {
        $a=SemanticNews::articleBySlug($slug);if(!$a)$this->notFound('Article unavailable');Http::publicCache(60,300,900);
        $lang=SemanticNews::locale((string)($a['language_locale']??''),(string)($a['language_code']??''));if($lang==='')$lang=(string)TenantData::setting('seo.default_language','en-IN');
        $authors=[];$authorUrls=[];foreach(($a['authors']??[])as$au){$url='/author/'.rawurlencode((string)$au['slug']);$authors[]='<a href="'.$this->e($url).'">'.$this->e($au['name']).'</a>';$authorUrls[]=Http::origin().$url;}
        $byline=$authors?implode(', ',$authors):$this->e((string)$a['publication_name']);$date=$a['published_at']?date('d M Y · H:i',strtotime((string)$a['published_at'])):'';
        $body='<article class="semantic-article"><header class="article-hero"><span class="eyebrow">NEWS ARTICLE</span><h1>'.$this->e($a['title']).'</h1>'.(!empty($a['deck'])?'<p class="article-deck">'.$this->e($a['deck']).'</p>':'').'<div class="article-byline"><span>By '.$byline.'</span><span>'.$this->e($date).'</span><span>'.$this->e((string)$a['publication_name']).'</span></div></header>';
        if(!empty($a['primary_image_url']))$body.='<figure class="article-lead-media"><img src="'.$this->e((string)$a['primary_image_url']).'" alt="'.$this->e((string)$a['title']).'" fetchpriority="high" decoding="async"></figure>';
        $body.='<div class="article-layout"><div class="article-body">'.$this->semanticParagraphs((string)$a['body']).'</div><aside class="article-context">';
        if(!empty($a['edition_slug'])&&!empty($a['page_number']))$body.='<div class="context-card"><span class="eyebrow">SOURCE EDITION</span><strong>'.$this->e((string)$a['publication_name']).'</strong><span>'.$this->e(date('d M Y',strtotime((string)$a['edition_date']))).' · Page '.(int)$a['page_number'].'</span><a href="/edition/'.$this->e((string)$a['edition_slug']).'/page/'.(int)$a['page_number'].'">Open original page →</a></div>';
        if(!empty($a['topics'])){$body.='<div class="context-card"><span class="eyebrow">TOPICS</span><div class="semantic-chips">';foreach($a['topics']as$t)$body.='<a href="/topic/'.$this->e($t['slug']).'">'.$this->e($t['name']).'</a>';$body.='</div></div>';}
        if(!empty($a['entities'])){$body.='<div class="context-card"><span class="eyebrow">MENTIONED</span><div class="semantic-chips">';foreach($a['entities']as$en)$body.='<a href="/entity/'.$this->e($en['slug']).'">'.$this->e($en['name']).'</a>';$body.='</div></div>';}
        $body.='</aside></div>';
        if(trim((string)($a['source_notes']??''))!=='')$body.='<section class="article-trust-note"><h2>Sources & reporting notes</h2>'.$this->semanticParagraphs((string)$a['source_notes']).'</section>';
        if(!empty($a['ai_assisted']))$body.='<section class="article-trust-note"><h2>AI assistance disclosure</h2><p>'.$this->e(trim((string)($a['ai_disclosure']??''))?:'AI-assisted tools were used in the production workflow. Editorial responsibility remains with the publisher.').'</p></section>';
        if(trim((string)($a['correction_note']??''))!=='')$body.='<section class="article-trust-note correction"><h2>Correction / update note</h2>'.$this->semanticParagraphs((string)$a['correction_note']).'</section>';
