        View::layout((string)$a['title'],$body,['brand'=>$this->brandName(),'description'=>$desc,'lang'=>$lang,'canonical_url'=>$canonical,'og_type'=>'article','og_title'=>(string)$a['title'],'og_description'=>$desc,'social_image'=>(string)($a['primary_image_url']??''),'alternates'=>SemanticNews::translationAlternates($a),'structured_data'=>SemanticNews::articleStructuredData($a),'article_published_time'=>!empty($a['published_at'])?gmdate('c',strtotime((string)$a['published_at'])):'','article_modified_time'=>!empty($a['updated_at'])?gmdate('c',strtotime((string)$a['updated_at'])):'','article_section'=>(string)($a['section_name']??''),'article_authors'=>$authorUrls,'navigation_scope'=>['publication_guid'=>$a['publication_guid']??null,'city_guid'=>$a['city_guid']??null,'language_guid'=>$a['language_guid']??null]]);
