    private function semanticParagraphs(string $text): string
    {
        $text=trim($text);if($text==='')return'';$parts=preg_split('/\R{2,}/u',$text)?:[$text];$h='';foreach($parts as$p){$p=trim(preg_replace('/\R/u',' ',(string)$p));if($p!=='')$h.='<p>'.$this->e($p).'</p>';}return$h;
    }

